"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(s):
    maxLen = 0
    start = 0
    seen = {}
    for i in range(0, len(s)):
        if ((s[i] in seen) and (seen[s[i]] >= start)):
            start = (seen[s[i]] + 1)
        seen[s[i]] = i
        maxLen = max(maxLen, ((i - start) + 1))
    return maxLen
